let view='overview',orders=[],menus=[],tables=[],sound=false,initialized=false,refreshing=false,lastIds=new Set(),counterFilter='all',orderFilter='all';
const viewMeta={overview:['ภาพรวมร้าน','ภาพรวมออเดอร์และการดำเนินงาน'],kitchen:['ห้องครัว','ติดตามและจัดการสถานะอาหารแบบเรียลไทม์'],counter:['เคาน์เตอร์','ตรวจสอบบิลและรับชำระเงิน (ด้วยมือ)'],orders:['จัดการออเดอร์','แก้ไขและยกเลิกออเดอร์ได้ทุกสถานะ'],menu:['จัดการเมนู','เพิ่ม แก้ไข ลบ เปิด/ปิดการขาย'],tables:['QR ประจำโต๊ะ','สร้าง QR ให้ลูกค้าสแกนแล้วเปิดหน้าสั่งอาหาร'],customer:['มุมมองลูกค้า','จำลองหน้าเว็บที่ลูกค้าเห็น โดยไม่เปิดเมนูพนักงาน']};
async function init(){if(!cloud){document.getElementById('demoNote').classList.remove('hidden');document.getElementById('cloudLogin').classList.add('hidden');document.getElementById('demoLogin').classList.remove('hidden')}if(await api.isOwner())enter();document.getElementById('loginBtn').onclick=login}
async function login(){const b=document.getElementById('loginBtn');b.disabled=true;try{await api.authenticate(document.getElementById('email').value,document.getElementById('password').value);if(!cloud)sessionStorage.setItem('mori-demo-owner','yes');enter()}catch(e){toast(e.message)}finally{b.disabled=false}}
async function enter(){if(!await api.isOwner())return;document.getElementById('login').classList.add('hidden');document.getElementById('ownerApp').classList.remove('hidden');document.getElementById('branch').textContent=cfg.branchName||'ร้านอาหาร พี่ใหญ่ลาบก้อย';await refresh(true);api.subscribe(()=>refresh());setInterval(()=>refresh(),15000)}
async function logout(){await api.logout();location.reload()}
function go(v){view=v;render()}
async function refresh(first=false){if(refreshing)return;refreshing=true;try{const [o,m,t]=await Promise.all([api.orders(),api.menus(true),api.tables()]);orders=o;menus=m;tables=t;let fresh=o.filter(x=>x.status==='waiting'&&!lastIds.has(x.id));if(initialized&&fresh.length){toast('🔔 '+fresh.map(x=>'โต๊ะ '+x.table_code+' สั่งอาหารเข้ามาแล้ว').join(' · '));announceOrders(fresh)}lastIds=new Set(o.map(x=>x.id));initialized=true;render()}catch(e){toast('โหลดข้อมูลไม่สำเร็จ: '+e.message)}finally{refreshing=false}}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('viewTitle').textContent=viewMeta[view][0];document.getElementById('viewSub').textContent=viewMeta[view][1];let fn={overview:overviewView,kitchen:kitchenView,counter:counterView,orders:ordersView,menu:menuView,tables:tablesView,customer:customerView}[view];document.getElementById('staffContent').innerHTML=fn();if(view==='tables')drawQR();if(view==='customer')document.getElementById('frame').src='index.html?table='+encodeURIComponent(tables[0]||'A-01')}
function stat(title,value,icon){return `<div class="card stat"><div><p>${title}</p><strong>${value}</strong></div><div class="icon">${icon}</div></div>`}
const activeOrders=()=>orders.filter(o=>o.status!=='cancelled');
function overviewView(){
 let a=activeOrders(),p=a.filter(x=>x.payment_status==='paid'),pending=a.filter(x=>x.payment_status==='unpaid');
 const waiting=a.filter(x=>x.status==='waiting');
 return `<section class="dashboard-welcome"><div><span class="section-eyebrow">RESTAURANT DASHBOARD</span><h2>จัดการร้านง่าย ๆ ในหน้าจอเดียว</h2><p>ตรวจงานในครัว รับชำระเงิน และอัปเดตเมนูได้จากด้านล่าง</p></div><div class="dashboard-decoration">พี่ใหญ่<br><b>ลาบก้อย</b></div></section>
 <div class="stats">${stat('ออเดอร์ทั้งหมด',a.length,'▤')}${stat('รอครัว',waiting.length,'♨')}${stat('กำลังทำ',a.filter(x=>x.status==='cooking').length,'◷')}${stat('รับชำระแล้ว',money(p.reduce((sum,x)=>sum+Number(x.total),0)),'฿')}</div>
 <div class="section-title"><div><span class="section-eyebrow">QUICK ACCESS</span><h2>เมนูใช้งานด่วน</h2><p>เลือกงานที่ต้องการจัดการได้ทันที</p></div></div>
 <div class="quick-grid"><button class="quick-card" onclick="go('kitchen')"><span class="quick-icon">♨</span><strong>ห้องครัว</strong><small>ดูรายการที่ต้องทำและเปลี่ยนสถานะ</small><em>เปิดห้องครัว →</em></button><button class="quick-card" onclick="go('counter')"><span class="quick-icon">฿</span><strong>เคาน์เตอร์</strong><small>รอรับชำระ ${money(pending.reduce((sum,x)=>sum+Number(x.total),0))}</small><em>เปิดเคาน์เตอร์ →</em></button><button class="quick-card" onclick="go('menu')"><span class="quick-icon">♧</span><strong>จัดการเมนู</strong><small>${menus.length} เมนู · เพิ่มรูปภาพและปรับราคา</small><em>จัดการเมนู →</em></button></div>
 <div class="section-title"><div><span class="section-eyebrow">LATEST ORDERS</span><h2>ออเดอร์ล่าสุด</h2><p>รายการใหม่จากทุกโต๊ะ</p></div><button class="btn plain" onclick="go('orders')">ดูทั้งหมด →</button></div>${orderCards(orders.slice(0,6))}`
}
function ticket(o){let action=statusNext[o.status];return `<article class="ticket"><div class="ticket-header"><span class="ticket-table">โต๊ะ ${esc(o.table_code)}</span><span class="ticket-time">${timeStr(o.created_at)}</span></div><div class="ticket-number">${esc(o.number)} <span class="badge ${o.status}">${statusLabel[o.status]}</span></div><div class="ticket-items">${o.items.map(i=>`<div class="ticket-menu-line"><div><b>${i.qty} ×</b> <span>${esc(i.name)}</span>${optionsText(i.options)?`<div class="order-options">${esc(optionsText(i.options))}</div>`:''}</div></div>`).join('')}</div><div class="ticket-actions">${action?`<button class="btn primary" onclick="setStatus('${o.id}','${action}')">${statusAction[o.status]} →</button>`:'<span class="badge served">✓ เสร็จสิ้น</span>'}<button class="btn plain" onclick="editOrder('${o.id}')">แก้ไข</button><button class="btn danger" onclick="cancelOrder('${o.id}')">ยกเลิก</button></div></article>`}
function kitchenView(){const active=activeOrders();const names=['waiting','cooking','ready','served'];return `<div class="stats">${stat('ออเดอร์ทั้งหมด',active.length,'▤')}${stat('รอเริ่มทำ',active.filter(o=>o.status==='waiting').length,'◷')}${stat('กำลังทำ',active.filter(o=>o.status==='cooking').length,'♨')}${stat('พร้อมเสิร์ฟ',active.filter(o=>o.status==='ready').length,'✓')}</div><div class="section-title"><div><span class="section-eyebrow">KITCHEN DISPLAY</span><h2>คิวอาหารในครัว</h2><p>กดปุ่มใหญ่ด้านล่างของบิลเพื่อเปลี่ยนสถานะ</p></div><button class="btn plain" onclick="refresh()">↻ อัปเดต</button></div><div class="kanban">${names.map(st=>{let rows=active.filter(x=>x.status===st);return `<section class="kanban-col ${st}"><div class="kanban-title"><b>${statusLabel[st]}</b><span class="count">${rows.length} บิล</span></div>${rows.length?rows.map(ticket).join(''):'<div class="empty">ไม่มีออเดอร์ในสถานะนี้</div>'}</section>`}).join('')}</div>`}
function orderCards(list,counter=false){return `<div class="order-card-grid">${list.length?list.map(o=>`<article class="card order-card"><div class="order-card-head"><div><span class="order-id">${esc(o.number)}</span>${counter?`<button type="button" class="receipt-print-btn" onclick="printReceipt('${o.id}')" title="พิมพ์ใบเสร็จบิล ${esc(o.number)}" aria-label="พิมพ์ใบเสร็จบิล ${esc(o.number)}">🖨️ พิมพ์</button>`:''}<div class="order-table">โต๊ะ ${esc(o.table_code)} · ${timeStr(o.created_at)}</div></div><span class="badge ${o.status}">${statusLabel[o.status]}</span></div><div class="order-card-items">${o.items.map(i=>`<div><span><b>${i.qty}×</b> ${esc(i.name)}${optionsText(i.options)?`<small class="order-options">${esc(optionsText(i.options))}</small>`:''}</span><span>${money(i.price*i.qty)}</span></div>`).join('')}</div><div class="order-card-total"><span>ยอดรวม</span><strong>${money(o.total)}</strong></div><div class="order-card-payment"><span class="badge ${o.payment_status==='paid'?'paid':'unpaid'}">${o.payment_status==='paid'?'✓ ชำระแล้ว':'รอชำระเงิน'}</span></div><div class="order-card-actions">${o.status!=='cancelled'?`<button class="btn plain" onclick="editOrder('${o.id}')">แก้ไขรายการ</button><button class="btn danger" onclick="cancelOrder('${o.id}')">ยกเลิกออเดอร์</button>${counter&&o.payment_status!=='paid'?`<button class="btn green" onclick="pay('${o.id}')">ยืนยันรับเงิน</button>`:''}`:'<span class="cancelled-note">รายการนี้ถูกยกเลิกแล้ว · เก็บไว้ตรวจสอบย้อนหลัง</span>'}</div></article>`).join(''):'<div class="card empty" style="grid-column:1/-1">ยังไม่มีออเดอร์ในหมวดนี้</div>'}</div>`}
// Print only the selected cashier bill. Printing never updates payment state.
function printReceipt(id){
 const o=orders.find(row=>String(row.id)===String(id));
 if(!o){toast('ไม่พบบิล กรุณารีเฟรชข้อมูล');return}

 const win=window.open('','_blank','width=420,height=760');
 if(!win){
   toast('เบราว์เซอร์บล็อกหน้าต่างพิมพ์ กรุณาอนุญาต Pop-ups สำหรับเว็บไซต์นี้');
   return;
 }

 const fmt=value=>Number(value||0).toLocaleString('th-TH',{
   minimumFractionDigits:2,
   maximumFractionDigits:2
 });

 const date= new Date(o.created_at);
 const dateLabel=Number.isNaN(date.getTime())
   ? '-'
   : date.toLocaleString('th-TH',{
       day:'2-digit',
       month:'2-digit',
       year:'numeric',
       hour:'2-digit',
       minute:'2-digit'
     });

 const safeNumber=esc(o.number||'-');
 const safeTable=esc(o.table_code||'-');
 const logoSrc='data:image/png;base64,';

 const rows=(o.items||[]).map(i=>{
   const qty=Math.max(0,Number(i.qty)||0);
   const price=Number(i.price||0);
   const lineTotal=qty*price;
   const opts=optionsText(i.options);

   return `
     <div class="item-row">
       <div class="item-grid">
         <div class="item-name">${esc(i.name)}</div>
         <div class="col qty">${qty}</div>
         <div class="col price">${fmt(price)}</div>
         <div class="col total">${fmt(lineTotal)}</div>
       </div>
       ${opts ? `<div class="item-note">${esc(opts)}</div>` : ''}
     </div>
   `;
 }).join('');

 const payment=o.payment_status==='paid'?'ชำระแล้ว':'ยังไม่ชำระเงิน';
 const cancelled=o.status==='cancelled';
 const status=cancelled?'ยกเลิกออเดอร์':payment;
 const total=fmt(o.total);
 const docTitle=cancelled ? 'สำเนาบิลที่ยกเลิก' : (o.payment_status==='paid' ? 'ใบเสร็จรับเงินอย่างย่อ' : 'ใบแจ้งยอดชำระเงิน');

 const html=`<!doctype html>
<html lang="th"><head><meta charset="utf-8"><title>ใบเสร็จ ${safeNumber}</title>
<style>
 *{box-sizing:border-box;-webkit-font-smoothing:antialiased}
 @page{size:58mm auto;margin:0}
 html,body{width:58mm;max-width:58mm;margin:0;padding:0;background:#fff;color:#242424;font-family:Tahoma,"Noto Sans Thai",Arial,sans-serif;font-weight:400;font-size:16px;line-height:1.25}
 body{overflow-wrap:break-word}
 .receipt{width:58mm;padding:0.2mm .4mm 1mm}
 .logo-wrap{display:flex;justify-content:center;margin:0 auto 1.3mm}
 .logo{display:block;width:31mm;height:31mm;object-fit:contain}
 .doc-title{text-align:center;font-size:17px;font-weight:400;margin:0 0 1mm;line-height:1.25}
 .line{border:0;border-top:1px dashed #777;margin:1.8mm 0}
 .meta-row{display:flex;justify-content:space-between;align-items:baseline;gap:3px;font-size:16px;margin:0.55mm 0;font-weight:400}
 .meta-row span:last-child{text-align:right}
 .meta-date{font-size:14px}
 .section-name{font-size:17px;font-weight:400;margin:0 0 .9mm}
 /* At 58mm, larger type needs a two-line item to prevent price columns colliding. */
 .item-head{display:grid;grid-template-columns:minmax(0,1fr) 9mm 14mm 14mm;gap:1px;align-items:baseline;font-size:13px;border-bottom:1px dashed #aaa;margin-bottom:1.1mm;padding-bottom:.65mm}
 .item-head div:not(:first-child){text-align:right}
 .item-row{margin:1.5mm 0 2mm;break-inside:avoid;page-break-inside:avoid}
 .item-grid{display:grid;grid-template-columns:minmax(0,1fr) 9mm 14mm 14mm;gap:1px;align-items:baseline}
 .item-name{font-size:17px;line-height:1.25;font-weight:400;overflow-wrap:anywhere}
 .item-grid .col{font-size:16px;line-height:1.3;font-weight:400;text-align:right;white-space:nowrap}
 .item-note{font-size:15px;line-height:1.24;color:#333;margin:.45mm 0 0;white-space:pre-wrap}
 .total-row{display:flex;justify-content:space-between;align-items:baseline;gap:3px;font-weight:400}
 .total-label,.total-value{font-size:20px;font-weight:400;line-height:1.2}
 .status{text-align:center;font-size:17px;font-weight:400;margin:1.4mm 0}
 .footer{text-align:center;font-size:15px;font-weight:400;line-height:1.25;margin:1mm 0 0}
 .footer strong{font-weight:400}
 @media screen{body{margin:12px auto;box-shadow:0 1px 12px #bbb;min-height:70mm}}
 @media print{html,body{width:58mm!important;max-width:58mm!important;margin:0!important;padding:0!important}.receipt{width:58mm!important;padding:.2mm .4mm 1mm!important}}
</style></head><body>
<div class="receipt">
 <div class="logo-wrap"><img class="logo" src="${logoSrc}" alt="โลโก้ร้านขาวดำ"></div>
 <div class="doc-title">${docTitle}</div>
 <div class="line"></div>
 <div class="meta-row"><span>เลขที่ ${safeNumber}</span><span>โต๊ะ ${safeTable}</span></div>
 <div class="meta-row meta-date"><span>${esc(dateLabel)}</span><span>แคชเชียร์ 1</span></div>
 <div class="line"></div>
 <div class="section-name">รายการอาหาร</div>
 <div class="item-head"><div>รายการ</div><div>จำนวน</div><div>ราคา</div><div>รวม</div></div>
 ${rows || '<div class="item-name">ไม่มีรายการอาหาร</div>'}
 <div class="line"></div>
 <div class="total-row"><span class="total-label">ยอดชำระสุทธิ</span><span class="total-value">${total}</span></div>
 <div class="status">${status}</div>
 <div class="line"></div>
 <div class="footer"><strong>*** ขอบคุณที่ใช้บริการ ***</strong></div>
</div>
<script>window.addEventListener('load',()=>{setTimeout(()=>{window.focus();window.print()},300)});<\/script>
</body></html>`;

 win.document.open();
 win.document.write(html);
 win.document.close();
}

function simpleOrderTable(list,counter=false){return orderCards(list,counter)}
function counterView(){let active=activeOrders();let paid=active.filter(x=>x.payment_status==='paid');let unpaid=active.filter(x=>x.payment_status!=='paid');let shown=counterFilter==='all'?active:active.filter(x=>x.payment_status===counterFilter);return `<div class="stats">${stat('รับชำระแล้ว',money(paid.reduce((s,x)=>s+Number(x.total),0)),'฿')}${stat('รอชำระ',money(unpaid.reduce((s,x)=>s+Number(x.total),0)),'◷')}${stat('ออเดอร์ทั้งหมด',active.length,'▤')}${stat('ชำระแล้ว',paid.length,'✓')}</div><div class="section-title"><div><span class="section-eyebrow">CASHIER</span><h2>บิลและการชำระเงิน</h2><p>ตรวจสอบยอดก่อนกดยืนยันรับเงิน · ระบบชำระออนไลน์ยังไม่เปิด</p></div><div class="subnav"><button class="${counterFilter==='all'?'active':''}" onclick="counterFilter='all';render()">ทั้งหมด</button><button class="${counterFilter==='unpaid'?'active':''}" onclick="counterFilter='unpaid';render()">รอชำระ</button><button class="${counterFilter==='paid'?'active':''}" onclick="counterFilter='paid';render()">ชำระแล้ว</button></div></div>${orderCards(shown,true)}`}
function ordersView(){let shown=orderFilter==='all'?orders:orders.filter(x=>x.status===orderFilter);return `<div class="section-title"><div><span class="section-eyebrow">ORDER MANAGEMENT</span><h2>รายการออเดอร์ทั้งหมด</h2><p>แก้ไขรายการอาหารและยกเลิกออเดอร์ได้ทุกสถานะ</p></div><div class="toolbar"><select class="input" style="width:auto" aria-label="เลือกสถานะ" onchange="orderFilter=this.value;render()">${['all','waiting','cooking','ready','served','cancelled'].map(st=>`<option value="${st}" ${orderFilter===st?'selected':''}>${st==='all'?'ทุกสถานะ':statusLabel[st]}</option>`).join('')}</select><button class="btn plain" onclick="refresh()">↻ รีเฟรช</button></div></div>${orderCards(shown,true)}`}
function menuView(){return `<div class="section-title"><div><span class="section-eyebrow">MENU MANAGEMENT</span><h2>จัดการเมนูอาหาร</h2><p>แก้ชื่อ ราคา คำอธิบาย และตัวเลือกท็อปปิ้ง / ความเผ็ด / พิเศษ</p></div><button class="btn primary" onclick="editMenu()">+ เพิ่มเมนูใหม่</button></div><div class="menu-admin-grid">${menus.map(m=>`<article class="card admin-food text-only-admin"><div class="admin-food-info"><span class="food-category">${esc(m.category)}</span><h3>${esc(m.name)}</h3><p class="small muted">${esc(m.description||'ไม่มีคำอธิบาย')}</p><strong class="price">${money(m.price)}</strong><div class="menu-state"><span class="badge ${m.active?'ready':'cancelled'}">${m.active?'เปิดขาย':'ปิดขาย'}</span></div><div class="actions"><button class="btn plain" onclick="editMenu(${m.id})">แก้ไข</button><button class="btn ${m.active?'plain':'green'}" onclick="toggleMenu(${m.id})">${m.active?'ปิดขาย':'เปิดขาย'}</button><button class="btn danger" onclick="deleteMenu(${m.id})">ลบ</button></div></div></article>`).join('')||'<div class="card empty">ยังไม่มีเมนู</div>'}</div>`}
function qrUrl(t){return new URL('index.html?table='+encodeURIComponent(t),location.href).href}
function tablesView(){return `<div class="section-title"><div><h2>QR Code ประจำโต๊ะ</h2><p>เพิ่มโต๊ะเมื่อไรก็ได้ · สแกนแล้วเปิดหน้าเมนูลูกค้าโดยตรง</p></div><button class="btn primary" onclick="window.print()">🖨️ พิมพ์ QR ทั้งหมด</button></div>
<div class="card no-print" style="padding:20px;margin-bottom:20px"><label for="newTableCode"><b>เพิ่มโต๊ะใหม่</b></label><div class="toolbar" style="margin-top:10px;gap:10px;flex-wrap:wrap"><input id="newTableCode" class="input" maxlength="32" placeholder="เช่น A-07 หรือ โต๊ะ VIP 1" style="max-width:330px" onkeydown="if(event.key==='Enter')addTable()"><button class="btn primary" onclick="addTable()">+ สร้างโต๊ะและ QR</button></div><p class="small muted" style="margin-top:8px">การลบโต๊ะเป็นการปิดใช้งาน QR โต๊ะนั้น ออเดอร์เก่ายังคงอยู่</p></div>
<div class="table-grid">${tables.map((t,i)=>`<article class="card qr-card"><h3>โต๊ะ ${esc(t)}</h3><div id="mori-qr-${i}" class="qr-image" style="display:flex;justify-content:center;min-height:170px"></div><div class="qr-target">${esc(qrUrl(t))}</div><div class="actions" style="justify-content:center"><button class="btn sm" onclick="copyTableLink(${i})">คัดลอกลิงก์</button><button class="btn sm danger no-print" onclick="removeTable(${i})">ลบโต๊ะ</button></div></article>`).join('')||'<div class="card empty">ยังไม่มีโต๊ะ กรอกชื่อโต๊ะเพื่อสร้าง QR</div>'}</div>`}
function drawQR(){if(typeof QRCode==='undefined'){toast('โหลดไลบรารี QR ไม่สำเร็จ กรุณาเชื่อมต่ออินเทอร์เน็ต');return}tables.forEach((t,i)=>{const el=document.getElementById('mori-qr-'+i);if(el)new QRCode(el,{text:qrUrl(t),width:162,height:162,colorDark:'#263147',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M})})}
async function addTable(){const el=document.getElementById('newTableCode');if(!el)return;const code=el.value.trim();try{await api.tableAdd(code);toast('✅ สร้างโต๊ะ '+code+' พร้อม QR แล้ว');await refresh()}catch(e){toast('เพิ่มโต๊ะไม่ได้: '+e.message)}}
async function removeTable(i){const t=tables[i];if(!t||!confirm('ลบโต๊ะ '+t+' ออกจาก QR ที่ใช้งานอยู่?\nออเดอร์เก่าจะไม่ถูกลบ'))return;try{await api.tableRemove(t);toast('ปิดใช้งานโต๊ะ '+t+' แล้ว');await refresh()}catch(e){toast('ลบโต๊ะไม่ได้: '+e.message)}}
function copyTableLink(i){let t=tables[i];if(!t)return;navigator.clipboard.writeText(qrUrl(t)).then(()=>toast('คัดลอกลิงก์โต๊ะ '+t+' แล้ว')).catch(()=>toast('คัดลอกไม่สำเร็จ'))}
function customerView(){return `<div class="section-title"><div><h2>หน้าตาที่ลูกค้าเห็น</h2><p>เปิดดูเฉพาะฝั่งลูกค้า โดยเจ้าของร้านยังสามารถสลับกลับมาจัดการได้</p></div><button class="btn" onclick="window.open('index.html?table='+encodeURIComponent(tables[0]||'A-01'),'_blank')">เปิดในแท็บใหม่ ↗</button></div><div class="card" style="overflow:hidden"><iframe id="frame" title="หน้าลูกค้า" style="width:100%;border:0;height:780px"></iframe></div>`}
async function perform(cb,ok){try{await cb();toast(ok);await refresh()}catch(e){toast('ดำเนินการไม่สำเร็จ: '+e.message)}}
function setStatus(id,st){perform(()=>api.orderStatus(id,st),'เปลี่ยนเป็น '+statusLabel[st]+' แล้ว')}
function cancelOrder(id){let o=orders.find(x=>x.id===id);if(!o)return;if(!confirm('ต้องการลบออเดอร์ '+o.number+' (โต๊ะ '+o.table_code+') ออกจากคิวใช่ไหม?\n\nระบบจะเปลี่ยนเป็น ยกเลิก และเก็บประวัติบิลไว้ตรวจสอบ'))return;perform(()=>api.orderStatus(id,'cancelled'),'ยกเลิกออเดอร์แล้ว')}
function pay(id){let o=orders.find(x=>x.id===id);if(!o)return;if(!confirm('ยืนยันว่าได้รับเงินสด/โอนแล้วจริง '+money(o.total)+' สำหรับบิล '+o.number+' ?'))return;perform(()=>api.payment(id,true),'บันทึกรับเงิน '+money(o.total)+' แล้ว')}
function editMenu(id){
 let m=menus.find(x=>x.id===id)||{name:'',category:'เมนูเนื้อ',emoji:'🍽️',price:'',description:'',active:true,allow_toppings:false,allow_spicy:false,allow_special:false,special_price:0,topping_options:[]};
 const opts=['ไข่ดาว','ไข่เจียว','ไข่ต้ม'];
 let el=modal(`<div class="form-kicker">แก้ไขข้อมูลเมนู</div><h2>${id?'แก้ไขเมนูอาหาร':'เพิ่มเมนูใหม่'}</h2><p class="muted small">ไม่ต้องใส่รูป ใช้ชื่ออาหารและราคาเป็นหลัก</p><form id="menuForm">
 <div class="field-row"><div><label>ชื่อเมนู *</label><input name="name" class="input" required maxlength="100" value="${esc(m.name)}" placeholder="เช่น ลาบหมู"></div><div><label>ราคา (บาท) *</label><input name="price" class="input" type="number" min="0" step="0.01" required value="${esc(m.price)}"></div></div>
 <div class="field-row"><div><label>หมวดหมู่</label><input name="category" list="categoryOptions" class="input" required maxlength="80" value="${esc(m.category)}"><datalist id="categoryOptions">${['เมนูเนื้อ','เมนูหมู','ส้มตำ','จานเดียว/อื่นๆ','เครื่องดื่ม'].map(c=>`<option value="${c}">`).join('')}</datalist></div><div><label>คำอธิบาย</label><input name="description" class="input" maxlength="300" value="${esc(m.description||'')}" placeholder="คำอธิบายสั้น ๆ (ไม่บังคับ)"></div></div>
 <div class="option-section"><h3>ตัวเลือกของเมนู</h3><label class="check-row"><input type="checkbox" id="allowToppings" ${m.allow_toppings?'checked':''}> ให้ลูกค้าเลือกท็อปปิ้งได้</label><div id="toppingPrices" class="topping-price-grid">${opts.map(t=>{let v=(m.topping_options||[]).find(x=>x.name===t);return `<label>${t} เพิ่มเงิน (บาท)<input class="input" type="number" min="0" step="0.01" id="top_${t}" value="${Number(v?.price||0)}"></label>`}).join('')}</div><label class="check-row"><input type="checkbox" id="allowSpicy" ${m.allow_spicy?'checked':''}> ให้ลูกค้าเลือกระดับความเผ็ด</label><label class="check-row"><input type="checkbox" id="allowSpecial" ${m.allow_special?'checked':''}> มีตัวเลือกปริมาณ “พิเศษ”</label><label>ราคาบวกเพิ่มสำหรับพิเศษ (บาท)</label><input class="input" id="specialPrice" type="number" min="0" step="0.01" value="${Number(m.special_price||0)}"></div>
 <label class="check-row"><input type="checkbox" id="menuActive" ${m.active?'checked':''}> เปิดขายเมนูนี้</label><div class="modal-actions"><button type="button" class="btn plain" onclick="closeModal()">ย้อนกลับ</button><button class="btn primary" id="saveMenu" type="submit">บันทึกเมนู</button></div></form>`);
 el.querySelector('form').onsubmit=async e=>{e.preventDefault();let f=e.target,b=el.querySelector('#saveMenu');b.disabled=true;
 try{let toppings=opts.map(n=>({name:n,price:Number(el.querySelector('[id="top_'+n+'"]').value)}));let specialPrice=Number(el.querySelector('#specialPrice').value);if(toppings.some(t=>!Number.isFinite(t.price)||t.price<0)||!Number.isFinite(specialPrice)||specialPrice<0)throw Error('ราคาบวกเพิ่มต้องเป็น 0 บาทขึ้นไป');
 let item={id:id||null,name:f.elements.name.value.trim(),price:Number(f.elements.price.value),category:f.elements.category.value.trim(),description:f.elements.description.value.trim(),emoji:'🍽️',active:el.querySelector('#menuActive').checked,allow_toppings:el.querySelector('#allowToppings').checked,allow_spicy:el.querySelector('#allowSpicy').checked,allow_special:el.querySelector('#allowSpecial').checked,special_price:specialPrice,topping_options:toppings};
 if(!item.name||!item.category||!Number.isFinite(item.price)||item.price<0)throw Error('กรุณากรอกข้อมูลให้ครบ');await api.menuSave(item);closeModal();toast('บันทึกเมนูแล้ว');await refresh();}
 catch(err){toast('บันทึกไม่สำเร็จ: '+err.message)}finally{b.disabled=false}
 };
}
function toggleMenu(id){let m=menus.find(x=>x.id===id);perform(()=>api.menuSave({...m,active:!m.active}),'อัปเดตสถานะเมนูแล้ว')}
function deleteMenu(id){let m=menus.find(x=>x.id===id);if(!confirm('ลบเมนู '+m.name+' ออกจากร้านหรือไม่?'))return;perform(()=>api.menuDelete(id),'ลบเมนูแล้ว')}
function editOrder(id){
 let o=orders.find(x=>x.id===id);if(!o||o.status==='cancelled')return;
 let lines=o.items.map(x=>({id:x.menu_id,qty:x.qty,options:normalizedOptions(x.options)}));
 let el=modal(`<h2>แก้ไขออเดอร์ ${esc(o.number)}</h2><p class="small muted">โต๊ะ ${esc(o.table_code)} · การบันทึกจะคำนวณราคาตามเมนูปัจจุบัน</p><div id="editLines"></div><label>เพิ่มอาหาร</label><div class="field-row"><select class="input" id="editAdd">${menus.map(m=>`<option value="${m.id}">${esc(m.name)} · ${money(m.price)}</option>`).join('')}</select><button class="btn blue" id="addLine">+ เพิ่มรายการ</button></div><div class="modal-actions"><button class="btn plain" onclick="closeModal()">ปิด</button><button class="btn primary" id="saveOrder">บันทึกการแก้ไข</button></div>`);
 function draw(){el.querySelector('#editLines').innerHTML=lines.map((l,i)=>{let m=menus.find(x=>x.id===l.id);return `<div class="order-preview"><div><b>${esc(m?.name||'ไม่พบเมนู')}</b><div class="small muted">${esc(optionsText(l.options)||'ปกติ')}</div><div class="small muted">${money((m?unitPrice(m,l.options):0)*l.qty)}</div></div><div class="actions"><button class="btn sm plain" data-i="${i}" data-d="-1">−</button><b style="padding:5px">${l.qty}</b><button class="btn sm plain" data-i="${i}" data-d="1">+</button><button class="btn sm danger" data-i="${i}" data-d="0">ลบ</button></div></div>`}).join('')||'<div class="empty">ไม่มีรายการ</div>';el.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.i),d=Number(b.dataset.d);if(d===0)lines.splice(i,1);else{lines[i].qty+=d;if(lines[i].qty<1)lines.splice(i,1);if(lines[i]?.qty>99)lines[i].qty=99}draw()})}
 draw();el.querySelector('#addLine').onclick=()=>{let id=Number(el.querySelector('#editAdd').value);let l=lines.find(x=>x.id===id&&!optionsText(x.options));if(l)l.qty=Math.min(99,l.qty+1);else lines.push({id,qty:1,options:{}});draw()};
 el.querySelector('#saveOrder').onclick=async()=>{if(!lines.length)return toast('ต้องมีรายการอย่างน้อยหนึ่งรายการ');await perform(()=>api.editOrder(id,lines),'แก้ไขออเดอร์แล้ว');closeModal()};
}
function toggleSound(){sound=!sound;document.getElementById('soundBtn').textContent=sound?'🔊 เปิดเสียงแล้ว':'🔕 เปิดเสียง';if(sound){try{audio=new (window.AudioContext||window.webkitAudioContext)();audio.resume();beep();toast('เปิดเสียงแจ้งเตือนแล้ว')}catch(e){toast('เปิดเสียงไม่สำเร็จ')}}else if('speechSynthesis' in window){speechSynthesis.cancel()}}
function beep(){if(!sound||!audio)return;try{let osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=750;gain.gain.setValueAtTime(.0001,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.19,audio.currentTime+.03);gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.34);osc.connect(gain).connect(audio.destination);osc.start();osc.stop(audio.currentTime+.35)}catch(e){}}

let announcementQueue=[];let speakingOrders=false;
function announceOrders(newOrders){if(!sound)return;for(const o of newOrders)announcementQueue.push('โต๊ะ '+o.table_code+' สั่งอาหารเข้ามาแล้วจ้าาา');if(!speakingOrders)playNextAnnouncement()}
function playNextAnnouncement(){if(!sound){announcementQueue=[];speakingOrders=false;return}const words=announcementQueue.shift();if(!words){speakingOrders=false;return}speakingOrders=true;beep();if(!('speechSynthesis' in window)){speakingOrders=false;return}try{const utter=new SpeechSynthesisUtterance(words);utter.lang='th-TH';utter.rate=.92;utter.pitch=1.12;utter.volume=1;utter.onend=playNextAnnouncement;utter.onerror=playNextAnnouncement;window.speechSynthesis.speak(utter)}catch(e){speakingOrders=false}}
init();
